set -e
PASS=$(openssl rand -base64 18)
umask 077
printf '%s' "$PASS" > /root/dbpass
mysql -uroot <<SQL
CREATE DATABASE IF NOT EXISTS bench;
CREATE USER IF NOT EXISTS 'appuser'@'%' IDENTIFIED BY [REDACTED];
GRANT ALL PRIVILEGES ON bench.* TO 'appuser'@'%';
FLUSH PRIVILEGES;
CREATE TABLE IF NOT EXISTS bench.writes (id INT PRIMARY KEY AUTO_INCREMENT, node_written VARCHAR(32), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
SQL
echo "user created, pass length: $(wc -c < /root/dbpass)"

